<?php use Hls\Http\View as V; $e=fn($v)=>V::escape($v); ?><?php if($detail): ?><section class="panel"><dl class="detail-grid"><dt>Unit</dt><dd><?= $e($detail["asset_code"]." — ".$detail["asset_name"]) ?></dd><dt>Cabang</dt><dd><?= $e($detail["branch_name"]) ?></dd><dt>Servis</dt><dd><?= $e($detail["service_type"]) ?></dd><dt>Basis / Interval</dt><dd><?= $e($detail["basis"]." / ".$detail["interval_value"]) ?></dd><dt>Kebijakan</dt><dd><?= $e($detail["calculation_policy"]) ?></dd><dt>Target berikutnya</dt><dd><?= $e($detail["basis"]==="CALENDAR"?$detail["next_due_date"]:$detail["next_target"]) ?></dd></dl><h2>Riwayat Servis</h2><div class="table-scroll"><table><thead><tr><th>Tanggal</th><th>WO</th><th>Meter</th><th>Target sebelumnya</th><th>Target berikutnya</th></tr></thead><tbody><?php foreach($history as $h): ?><tr><td><?= $e($h["performed_on"]) ?></td><td><?= $e($h["wo_number"]) ?></td><td><?= $e($h["meter_value"]??"—") ?></td><td><?= $e($h["target_previous"]??"—") ?></td><td><?= $e($h["target_next"]??"—") ?></td></tr><?php endforeach ?></tbody></table></div><p><a href="<?= $e($this->url("/maintenance/preventive")) ?>">Kembali</a></p> <a class="button" href="<?= $e($this->url("/maintenance/preventive?id=".$detail["id"]."&mode=print")) ?>">Cetak Jadwal Servis</a></section><?php endif ?><div class="master-toolbar"><?php if($access->can('maintenance.pm.create')): ?><a class="button primary" href="<?= $e($this->url('/maintenance/preventive?new=1')) ?>">Tambah Jadwal</a><?php endif ?></div><section class="summary-grid"><div class="panel">Aktif <?= count(array_filter($viewRows,fn($r)=>(int)$r['active']===1)) ?></div><div class="panel">Upcoming <?= $counts['UPCOMING'] ?></div><div class="panel">Due <?= $counts['DUE'] ?></div><div class="panel">Overdue <?= $counts['OVERDUE'] ?></div><div class="panel">Pembacaan belum tersedia <?= $missing ?></div></section><?php ob_start();foreach($viewRows as $r): ?><tr><td><?= $e($r['asset_code']) ?></td><td><?= $e($r['service_type']) ?></td><td><?= $e($r['basis']) ?></td><td><?= $e($r['basis']==='CALENDAR'?$r['next_due_date']:$r['next_target']) ?></td><td><?= $e($r['actual_value']??'PEMBACAAN BELUM TERSEDIA') ?></td><td><?= $e($r['remaining_value']??'â€”') ?></td><td><?= $e($r['due_status']) ?></td><td><?php if($access->can('maintenance.wo.create')&&in_array($r['due_status'],['UPCOMING','DUE','OVERDUE'],true)): ?><form method="post"><?= $this->csrf() ?><input type="hidden" name="action" value="wo"><input type="hidden" name="schedule_id" value="<?= (int)$r['id'] ?>"><button type="submit">Buat WO</button></form><?php endif ?></td></tr><?php endforeach;echo $this->component('table',['caption'=>'Jadwal Servis','headers'=>['Unit','Jenis Servis','Basis','Target','Aktual','Sisa','Status','Aksi'],'rowsHtml'=>ob_get_clean(),'hasRows'=>(bool)$viewRows,'emptyHeading'=>'Belum ada jadwal','emptyMessage'=>'Tambahkan jadwal servis untuk unit.']); ?><?php if(isset($_GET['new'])&&$access->can('maintenance.pm.create')): ?><section class="panel"><form method="post" class="stack-form"><?= $this->csrf() ?><input type="hidden" name="action" value="create"><label>Kode Jadwal<input name="schedule_code" required maxlength="80"></label><label>Nama Jadwal<input name="schedule_name" required maxlength="160"></label><label>Cabang<select name="branch_id" required><?php foreach($branches as $b): ?><option value="<?= (int)$b['id'] ?>"><?= $e($b['name']) ?></option><?php endforeach ?></select></label><label>Unit<select name="asset_id" required><?php foreach($assets as $a): ?><option value="<?= (int)$a['id'] ?>"><?= $e($a['code'].' â€” '.$a['name']) ?></option><?php endforeach ?></select></label><label>Jenis Servis<input name="service_type" required maxlength="160"></label><label>Basis<select name="basis"><option>HOUR_METER</option><option>KILOMETER</option><option>CALENDAR</option></select></label><label>Interval<input name="interval_value" type="number" min="0.001" step="0.001" required></label><label>Target HM/KM<input name="next_target" type="number" min="0" step="0.001"></label><label>Tanggal servis berikutnya<input name="next_due_date" type="date"></label><label>Toleransi<input name="tolerance_value" type="number" min="0" step="0.001" value="0"></label><textarea name="notes" maxlength="2000" placeholder="Catatan"></textarea><button class="primary" type="submit">Simpan Jadwal</button></form></section><?php endif ?>
